const ApplicationsDatapointSchema = z
  .object({
    count: z.float64().exactOptional().openapi({ description: 'Count associated with timestamp' }),
    time: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({ description: 'Timestamp for the related count.' }),
  })
  .openapi({ required: [] })
  .openapi('ApplicationsDatapoint')

const ApplicationsSeriesSchema = z
  .object({
    datapoints: z
      .array(ApplicationsDatapointSchema)
      .exactOptional()
      .openapi({ description: 'Collection of samples with time and value.' }),
    target: z
      .string()
      .exactOptional()
      .openapi({ description: 'Target to which to datapoints apply.' }),
  })
  .openapi({ required: [] })
  .openapi('ApplicationsSeries')

const ApplicationsApiUsageSchema = z
  .object({
    apiCalls: z
      .array(ApplicationsSeriesSchema)
      .exactOptional()
      .openapi({ description: 'Counts for on API calls made for the time range.' }),
    throttledRequests: z
      .array(ApplicationsSeriesSchema)
      .exactOptional()
      .openapi({
        description:
          'Instances of blocked requests or requests that crossed the warn threshold during the time range.',
      }),
  })
  .openapi({ required: [] })
  .openapi('ApplicationsApiUsage')

const UserUserInfoCardSchema = z
  .object({
    applicableMembershipTypes: z
      .array(
        z
          .int32()
          .openapi({
            description:
              'The types of membership the Accounts system supports. This is the external facing enum used in place of the internal-only Bungie.SharedDefinitions.MembershipType.',
            'x-enum-reference': { $ref: '#/components/schemas/schema7' },
          }),
      )
      .exactOptional()
      .openapi({
        description:
          'The list of Membership Types indicating the platforms on which this Membership can be used.\r\n Not in Cross Save = its original membership type. Cross Save Primary = Any membership types it is overridding, and its original membership type Cross Save Overridden = Empty list',
      }),
    bungieGlobalDisplayName: z
      .string()
      .exactOptional()
      .openapi({ description: 'The bungie global display name, if set.' }),
    bungieGlobalDisplayNameCode: z
      .int()
      .exactOptional()
      .openapi({ description: 'The bungie global display name code, if set.' }),
    crossSaveOverride: z
      .int32()
      .exactOptional()
      .openapi({
        description:
          'If there is a cross save override in effect, this value will tell you the type that is overridding this one.',
        'x-enum-reference': { $ref: '#/components/schemas/schema7' },
      }),
    displayName: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Display Name the player has chosen for themselves. The display name is optional when the data type is used as input to a platform API.',
      }),
    iconPath: z.string().exactOptional().openapi({ description: 'URL the Icon if available.' }),
    isPublic: z
      .boolean()
      .exactOptional()
      .openapi({ description: 'If True, this is a public user membership.' }),
    membershipId: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .exactOptional()
      .openapi({
        type: 'integer',
        format: 'int64',
        description: 'Membership ID as they user is known in the Accounts service',
      }),
    membershipType: z
      .int32()
      .exactOptional()
      .openapi({
        description: 'Type of the membership. Not necessarily the native type.',
        'x-enum-reference': { $ref: '#/components/schemas/schema7' },
      }),
    supplementalDisplayName: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'A platform specific additional display name - ex: psn Real Name, bnet Unique Name, etc.',
      }),
  })
  .openapi({
    description:
      'This contract supplies basic information commonly used to display a minimal amount of information about a user. Take care to not add more properties here unless the property applies in all (or at least the majority) of the situations where UserInfoCard is used. Avoid adding game specific or platform specific details here. In cases where UserInfoCard is a subset of the data needed in a contract, use UserInfoCard as a property of other contracts.',
    required: [],
  })
  .openapi('UserUserInfoCard')

