const ApplicationsApplicationSchema = z
  .object({
    applicationId: z
      .int32()
      .exactOptional()
      .openapi({ description: 'Unique ID assigned to the application' }),
    creationDate: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({ description: 'Date the application was first added to our database.' }),
    firstPublished: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        description: "Date the first time the application status entered the 'Public' status.",
      }),
    link: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Link to website for the application where a user can learn more about the app.',
      }),
    name: z.string().exactOptional().openapi({ description: 'Name of the application' }),
    origin: z
      .string()
      .exactOptional()
      .openapi({
        description: 'Value of the Origin header sent in requests generated by this application.',
      }),
    overrideAuthorizeViewName: z
      .string()
      .exactOptional()
      .openapi({ description: 'An optional override for the Authorize view name.' }),
    redirectUrl: z
      .string()
      .exactOptional()
      .openapi({
        description: "URL used to pass the user's authorization code to the application",
      }),
    scope: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .exactOptional()
      .openapi({
        type: 'integer',
        format: 'int64',
        description: 'Permissions the application needs to work',
      }),
    status: z
      .int32()
      .exactOptional()
      .openapi({
        description: 'Current status of the application.',
        'x-enum-reference': { $ref: '#/components/schemas/schema5' },
      }),
    statusChanged: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({ description: 'Date the application status last changed.' }),
    team: z
      .array(ApplicationsApplicationDeveloperSchema)
      .exactOptional()
      .openapi({
        description:
          'List of team members who manage this application on Bungie.net. Will always consist of at least the application owner.',
      }),
  })
  .openapi({ required: [] })
  .openapi('ApplicationsApplication')

