const DestinyDefinitionsDestinyVendorItemQuantitySchema = z
  .object({
    hasConditionalVisibility: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'Indicates that this item quantity may be conditionally shown or hidden, based on various sources of state. For example: server flags, account state, or character progress.',
      }),
    itemHash: z
      .uint32()
      .exactOptional()
      .openapi({
        description:
          "The hash identifier for the item in question. Use it to look up the item's DestinyInventoryItemDefinition.",
        'x-mapped-definition': {
          $ref: '#/components/schemas/Destiny.Definitions.DestinyInventoryItemDefinition',
        },
      }),
    itemInstanceId: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .exactOptional()
      .openapi({
        type: 'integer',
        format: 'int64',
        description:
          "If this quantity is referring to a specific instance of an item, this will have the item's instance ID. Normally, this will be null.",
      }),
    quantity: z
      .int32()
      .exactOptional()
      .openapi({
        description:
          'The amount of the item needed/available depending on the context of where DestinyItemQuantity is being used.',
      }),
  })
  .openapi({
    description:
      "In addition to item quantity information for vendor prices, this also has any optional information that may exist about how the item's quantity can be modified. (unfortunately not information that is able to be read outside of the BNet servers, but it's there)",
    required: [],
  })
  .openapi('DestinyDefinitionsDestinyVendorItemQuantity')

