const Schema73Schema = z
  .union([z.literal('0'), z.literal('1'), z.literal('2'), z.literal('4'), z.literal('8')])
  .openapi({
    description:
      'Indicates how a socket is populated, and where you should look for valid plug data.\r\n This is a flags enumeration/bitmask field, as you may have to look in multiple sources across multiple components for valid plugs.\r\n For instance, a socket could have plugs that are sourced from its own definition, as well as plugs that are sourced from Character-scoped AND profile-scoped Plug Sets. Only by combining plug data for every indicated source will you be able to know all of the plugs available for a socket.',
    'x-enum-values': [
      {
        description: "If there's no way we can detect to insert new plugs.",
        identifier: 'None',
        numericValue: '0',
      },
      {
        description:
          "Use plugs found in the player's inventory, based on the socket type rules (see DestinySocketTypeDefinition for more info)\r\nNote that a socket - like Shaders - can have *both* reusable plugs and inventory items inserted theoretically.",
        identifier: 'InventorySourced',
        numericValue: '1',
      },
      {
        description:
          'Use the DestinyItemSocketsComponent.sockets.reusablePlugs property to determine which plugs are valid for this socket. This may have to be combined with other sources, such as plug sets, if those flags are set.\r\n Note that "Reusable" plugs may not necessarily come from a plug set, nor from the "reusablePlugItems" in the socket\'s Definition data. They can sometimes be "randomized" in which case the only source of truth at the moment is still the runtime DestinyItemSocketsComponent.sockets.reusablePlugs property.',
        identifier: 'ReusablePlugItems',
        numericValue: '2',
      },
      {
        description:
          'Use the ProfilePlugSets (DestinyProfileResponse.profilePlugSets) component data to determine which plugs are valid for this socket.',
        identifier: 'ProfilePlugSet',
        numericValue: '4',
      },
      {
        description:
          'Use the CharacterPlugSets (DestinyProfileResponse.characterPlugSets) component data to determine which plugs are valid for this socket.',
        identifier: 'CharacterPlugSet',
        numericValue: '8',
      },
    ],
  })
  .openapi('Schema73')

