export const getDestiny2ArmorySearchTypeSearchTermIndexRoute = createRoute({
  method: 'get',
  path: '/Destiny2/Armory/Search/{type}/{searchTerm}/',
  tags: ['Destiny2'],
  description: 'Gets a page list of Destiny items.',
  operationId: 'Destiny2.SearchDestinyEntities',
  request: {
    query: z.object({
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32(),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'Page number to return, starting with 0.',
            in: 'query',
            name: 'page',
            schema: { format: 'int32', type: 'integer' },
            required: false,
          },
        }),
    }),
    params: z.object({
      searchTerm: z
        .string()
        .openapi({
          param: {
            description: 'The string to use when searching for Destiny entities.',
            in: 'path',
            name: 'searchTerm',
            required: true,
            schema: { type: 'string' },
          },
        }),
      type: z
        .string()
        .openapi({
          param: {
            description:
              "The type of entity for whom you would like results. These correspond to the entity's definition contract name. For instance, if you are looking for items, this property should be 'DestinyInventoryItemDefinition'.",
            in: 'path',
            name: 'type',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description:
        "The results of a search for Destiny content. This will be improved on over time, I've been doing some experimenting to see what might be useful.",
      content: {
        '*/*': {
          schema: z
            .object({
              DetailedErrorTrace: z.string().exactOptional(),
              ErrorCode: z
                .int32()
                .exactOptional()
                .openapi({ 'x-enum-reference': { $ref: '#/components/schemas/schema1' } }),
              ErrorStatus: z.string().exactOptional(),
              Message: z.string().exactOptional(),
              MessageData: z.record(z.string(), z.string()).exactOptional(),
              Response: DestinyDefinitionsDestinyEntitySearchResultSchema.exactOptional(),
              ThrottleSeconds: z.int32().exactOptional(),
            })
            .openapi({ required: [] }),
        },
      },
    },
  },
})

