export const getUserGetBungieNetUserByIdIdIndexRoute = createRoute({
  method: 'get',
  path: '/User/GetBungieNetUserById/{id}/',
  tags: ['User'],
  description: 'Loads a bungienet user by membership id.',
  operationId: 'User.GetBungieNetUserById',
  request: {
    params: z.object({
      id: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            description: 'The requested Bungie.net membership id.',
            in: 'path',
            name: 'id',
            required: true,
            schema: { format: 'int64', type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description:
        'Look at the Response property for more information about the nature of this response',
      content: {
        '*/*': {
          schema: z
            .object({
              DetailedErrorTrace: z.string().exactOptional(),
              ErrorCode: z
                .int32()
                .exactOptional()
                .openapi({ 'x-enum-reference': { $ref: '#/components/schemas/schema1' } }),
              ErrorStatus: z.string().exactOptional(),
              Message: z.string().exactOptional(),
              MessageData: z.record(z.string(), z.string()).exactOptional(),
              Response: UserGeneralUserSchema.exactOptional(),
              ThrottleSeconds: z.int32().exactOptional(),
            })
            .openapi({ required: [] }),
        },
      },
    },
  },
})

