export const getUserGetMembershipFromHardLinkedCredentialCrTypeCredentialIndexRoute = createRoute({
  method: 'get',
  path: '/User/GetMembershipFromHardLinkedCredential/{crType}/{credential}/',
  tags: ['User'],
  description:
    'Gets any hard linked membership given a credential. Only works for credentials that are public (just SteamID64 right now). Cross Save aware.',
  operationId: 'User.GetMembershipFromHardLinkedCredential',
  request: {
    params: z.object({
      credential: z
        .string()
        .openapi({
          param: {
            description: 'The credential to look up. Must be a valid SteamID64.',
            in: 'path',
            name: 'credential',
            required: true,
            schema: { type: 'string' },
          },
        }),
      crType: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .openapi({
          param: {
            description: "The credential type. 'SteamId' is the only valid value at present.",
            in: 'path',
            name: 'crType',
            required: true,
            schema: { format: 'uint8', type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description:
        'Look at the Response property for more information about the nature of this response',
      content: {
        '*/*': {
          schema: z
            .object({
              DetailedErrorTrace: z.string().exactOptional(),
              ErrorCode: z
                .int32()
                .exactOptional()
                .openapi({ 'x-enum-reference': { $ref: '#/components/schemas/schema1' } }),
              ErrorStatus: z.string().exactOptional(),
              Message: z.string().exactOptional(),
              MessageData: z.record(z.string(), z.string()).exactOptional(),
              Response: UserHardLinkedUserMembershipSchema.exactOptional(),
              ThrottleSeconds: z.int32().exactOptional(),
            })
            .openapi({ required: [] }),
        },
      },
    },
  },
})

